    enonce: "<svg class=\"figure\" viewBox=\"0 0 300 210\" width=\"300\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" direction=\"ltr\" role=\"img\"><polygon points=\"81.7,47.4 224.8,42.2 215.1,154.0 78.4,159.2\" fill=\"#f7f8fc\" stroke=\"#2c3e50\" stroke-width=\"1.7\" stroke-linejoin=\"round\"/><circle cx=\"81.7\" cy=\"47.4\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"70.0\" y=\"42.0\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#2c3e50\" direction=\"ltr\">A</text><circle cx=\"224.8\" cy=\"42.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"236.5\" y=\"36.8\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#2c3e50\" direction=\"ltr\">B</text><circle cx=\"215.1\" cy=\"154.0\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"226.8\" y=\"167.4\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#2c3e50\" direction=\"ltr\">C</text><circle cx=\"78.4\" cy=\"159.2\" r=\"2.6\" fill=\"#2c3e50\"/><text x=\"66.7\" y=\"172.6\" font-size=\"14\" font-weight=\"700\" text-anchor=\"middle\" fill=\"#2c3e50\" direction=\"ltr\">D</text><line x1=\"153.1\" y1=\"39.8\" x2=\"153.4\" y2=\"49.7\" stroke=\"#5b4bd6\" stroke-width=\"1.6\"/><text x=\"154.5\" y=\"26.8\" font-size=\"13.5\" text-anchor=\"middle\" fill=\"#5b4bd6\" direction=\"ltr\">x</text><text x=\"241.9\" y=\"100.9\" font-size=\"13.5\" text-anchor=\"middle\" fill=\"#5b4bd6\" direction=\"ltr\">x + 3</text><line x1=\"146.9\" y1=\"161.6\" x2=\"146.6\" y2=\"151.6\" stroke=\"#5b4bd6\" stroke-width=\"1.6\"/><text x=\"145.4\" y=\"182.6\" font-size=\"13.5\" text-anchor=\"middle\" fill=\"#5b4bd6\" direction=\"ltr\">x</text><text x=\"58.1\" y=\"107.7\" font-size=\"13.5\" text-anchor=\"middle\" fill=\"#5b4bd6\" direction=\"ltr\">4</text></svg> ليكن P قيس محيط المضلّع ABCD: عبّر عن P بدلالة x",
    correction: [{"quoi":"تعريف المحيط","math":"المحيط هو مجموع أطوال جميع الأضلاع"},{"quoi":"نجمع الأضلاع","math":"<span dir=\"ltr\" class=\"expr\">P = x + (x + 3) + x + 4</span>"},{"quoi":"نزيل الأقواس","math":"<span dir=\"ltr\" class=\"expr\">P = x + x + 3 + x + 4</span>"},{"quoi":"نجمع حدود x","math":"مجموع حدود x يساوي 3 x"},{"quoi":"نجمع الأعداد","math":"مجموع الأعداد يساوي 7"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">P = 3 x + 7</span>"}],
