    correction: [{"quoi":"نترجم المعطى الجديد","math":"<span dir=\"ltr\" class=\"expr\">a - b = 11</span> إذن <span dir=\"ltr\" class=\"expr\">a = b + 11</span>"},{"quoi":"نعوّض في المساواة","math":"<span dir=\"ltr\" class=\"expr\">7(b + 11) + 6b = 272</span>"},{"quoi":"ننشر","math":"<span dir=\"ltr\" class=\"expr\">7b + 77 + 6b = 272</span>"},{"quoi":"نجمع حدود b","math":"<span dir=\"ltr\" class=\"expr\">13b + 77 = 272</span>"},{"quoi":"نعزل حدّ b","math":"<span dir=\"ltr\" class=\"expr\">13b = 272 - 77</span>"},{"quoi":"نحسب b","math":"<span dir=\"ltr\" class=\"expr\">b = 195 : 13 = 15</span>"},{"quoi":"نحسب a","math":"<span dir=\"ltr\" class=\"expr\">a = b + 11 = 26</span>"}],
